class Solution {
  private static boolean consecutive(char a, char b) {
    int d = Math.abs(a - b);
    return d == 1 || d == 25;
  }

  public String lexicographicallySmallestString(String s) {
    int n = s.length();
    boolean[][] rem = new boolean[n + 1][n + 1];
    for (int i = 0; i <= n; i++) rem[i][i] = true;
    for (int len = 2; len <= n; len += 2) {
      for (int i = 0; i + len <= n; i++) {
        int j = i + len;
        for (int k = i + 1; k < j && !rem[i][j]; k += 2) {
          if (consecutive(s.charAt(i), s.charAt(k)) && rem[i + 1][k] && rem[k + 1][j])
            rem[i][j] = true;
        }
      }
    }
    String[] dp = new String[n + 1];
    dp[n] = "";
    for (int i = n - 1; i >= 0; i--) {
      String best = s.charAt(i) + dp[i + 1];
      for (int j = i + 2; j <= n; j += 2) {
        if (rem[i][j] && dp[j].compareTo(best) < 0) best = dp[j];
      }
      dp[i] = best;
    }
    return dp[0];
  }
}
